  tools.structurizr["export-c4plantuml"]({ dsl, viewKey: "SystemContext" }),
  tools.structurizr["export-mermaid"]({ dsl, viewKey: "SystemContext" }),
]);

const show = (r) => r.status === "fulfilled" ? JSON.stringify(r.value).slice(0, 3000) : "REJECTED: " + (r.reason && r.reason.message || r.reason);
return { inspect: show(inspect), plantuml: show(plantuml), c4plantuml: show(c4plantuml), mermaid: show(mermaid) };

